// One-turn replay of the printer panel's request, as run_prompt_tests.py builds it.
// usage: node kobra3.mjs <runs> "<question>" [promptOverride.mjs]
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const HERE = 'C:/src/JusPrin/.claude/worktrees/printer-conversation-panel-af11cb/tests/printer_prompt';
const TOOLS = JSON.parse(readFileSync(`${HERE}/printer_tools.json`, 'utf8'));
const runs = Number(process.argv[2] || 10);
const question = process.argv[3] || "what's the current start g-code?";

const printer = { name: 'Anycubic Kobra 3', model: 'Anycubic Kobra 3', nozzle: 0.4, nozzles: [0.2, 0.4, 0.6, 0.8],
                  spools: [], connected: false, provider: 'host' };
const session = { mode: 'change', printerName: printer.name, blocks: [], context: { printer } };
const prompt = JSON.parse(execFileSync(process.execPath, [`${HERE}/render_prompt.mjs`], { input: JSON.stringify(session) }));
if (process.env.SHOW) console.log(prompt.instructions + '\n---\n' + prompt.opening + '\n---');

async function once() {
  const body = { model: process.env.MODEL || 'gpt-5.4-mini', store: false, parallel_tool_calls: false,
                 instructions: prompt.instructions, tools: TOOLS,
                 input: [{ role: 'assistant', content: prompt.opening },
                         { role: 'user', content: [{ type: 'input_text', text: question }] }] };
  const r = await fetch('https://api.openai.com/v1/responses', { method: 'POST', body: JSON.stringify(body),
    headers: { Authorization: 'Bearer ' + process.env.OPENAI_API_KEY, 'Content-Type': 'application/json' } });
  const j = await r.json();
  if (!r.ok) return 'ERROR ' + JSON.stringify(j).slice(0, 300);
  return j.output.map((o) => o.type === 'message' ? o.content.map((c) => c.text).join('')
                           : o.type === 'function_call' ? `[tool ${o.name} ${o.arguments}]` : '').filter(Boolean).join(' | ');
}
const results = await Promise.all(Array.from({ length: runs }, once));
results.forEach((t, i) => console.log(`${i + 1}: ${t.replace(/\n/g, ' / ')}`));
const says = results.filter((t) => /\badd(ed)?\b/i.test(t) && /connect/i.test(t)).length;
console.log(`\n"add or connect" replies: ${says} of ${runs}`);

