// Why does deepseek-v4-flash on OpenRouter answer badly when the conversation
// ends on an app note? Same conversation, the note placed several ways, sent
// through OpenRouter's chat completions (where the provider's chat template
// applies) and its Responses API (what the harness uses).
import { readFileSync } from 'node:fs';

const KEY = readFileSync('C:/Users/guitest/Downloads/openrouterkey.txt', 'utf8').trim();
const MODEL = process.env.MODEL || 'deepseek/deepseek-v4-flash';
const RUNS = Number(process.env.RUNS || 4);
const SYSTEM = 'You are a printer assistant. Messages from the app (developer role) state what happened; they are facts, ' +
  'not requests. After the app says a connection is verified, tell the person in one sentence and end with the line "Choices: Done".';
const BEFORE = [
  { role: 'user', content: 'it is at http://voron.local' },
  { role: 'assistant', content: "I'm checking it now; this can take up to 30 seconds." },
];
const NOTE = 'Connection to Voron 2.4 350 verified.';

const layouts = {
  'note as developer, last': [...BEFORE, { role: 'developer', content: NOTE }],
  'note as system, last': [...BEFORE, { role: 'system', content: NOTE }],
  'no note at all (ends on assistant)': [...BEFORE],
  'note as user, last': [...BEFORE, { role: 'user', content: '[App] ' + NOTE }],
};

async function chat(messages) {
  const r = await fetch('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST', headers: { Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: MODEL, messages: [{ role: 'system', content: SYSTEM }, ...messages],
                           ...(process.env.PROVIDER ? { provider: { order: [process.env.PROVIDER], allow_fallbacks: false } } : {}) }),
  });
  const j = await r.json();
  if (!r.ok) return { text: 'ERROR ' + JSON.stringify(j).slice(0, 200), provider: '?' };
  return { text: j.choices[0].message.content ?? '', provider: j.provider };
}

for (const [name, messages] of Object.entries(layouts)) {
  const results = await Promise.all(Array.from({ length: RUNS }, () => chat(messages)));
  console.log(`\n== ${name}`);
  for (const { text, provider } of results) console.log(`  [${provider}] ${JSON.stringify(text).slice(0, 180)}`);
}

